import{_ as a,C as n,c as i,o as s,j as t,G as l,ag as d,a as o}from"./chunks/framework.DZ_cNctr.js";const h="/docs/screenshots/nd2-image.webp",w=JSON.parse('{"title":"Nikon ND2 Viewer","description":"Free online Nikon ND2 viewer: open .nd2 files from NIS-Elements in your browser, with every channel, XY position, Z-stack and time series. Old and new ND2 files. From your disk or a link. Nothing to install.","frontmatter":{"title":"Nikon ND2 Viewer","description":"Free online Nikon ND2 viewer: open .nd2 files from NIS-Elements in your browser, with every channel, XY position, Z-stack and time series. Old and new ND2 files. From your disk or a link. Nothing to install."},"headers":[],"relativePath":"guides/nikon-nd2.md","filePath":"guides/nikon-nd2.md"}'),c={name:"guides/nikon-nd2.md"};function p(f,e,m,g,u,b){const r=n("OpenViewer");return s(),i("div",null,[e[0]||(e[0]=t("h1",{id:"nikon-nd2-viewer",tabindex:"-1"},[o("Nikon ND2 Viewer "),t("a",{class:"header-anchor",href:"#nikon-nd2-viewer","aria-label":'Permalink to "Nikon ND2 Viewer"'},"​")],-1)),e[1]||(e[1]=t("p",null,[o("Open "),t("code",null,".nd2"),o(" files from Nikon NIS-Elements, from today's files back to the first ND2 format. You get every channel, XY position, Z-stack and time series. ND2 files shared on Zenodo open by their link.")],-1)),l(r,{format:"ND2",example:"https://find-nuclei.github.io/examples/formats/HE_002.nd2",label:"an H&E section in ND2"}),e[2]||(e[2]=d('<p><img src="'+h+'" alt="HE_002.nd2 open in the viewer: an H&amp;E section from a Nikon colour camera, drawn as a colour photograph"></p><h2 id="how-to-open-an-nd2-file" tabindex="-1">How to Open an ND2 File <a class="header-anchor" href="#how-to-open-an-nd2-file" aria-label="Permalink to &quot;How to Open an ND2 File&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Working with many files?</p><p>Chrome and Edge on a computer open a whole folder as a <a href="./many-images.html">gallery</a>. Firefox and Safari open one file at a time.</p></div><ul><li><strong>One file on your disk</strong>, in any browser. Drop it on <a href="https://find-nuclei.github.io/" target="_blank" rel="noreferrer">the viewer</a>, or click <strong>Open Image</strong> and <strong>Choose File</strong>. See <a href="./local-files.html#open-a-file">Local Files</a>.</li><li><strong>A folder of ND2 files</strong>, in Chrome and Edge. One file opens. Several show a list with a picture of each, and files one folder down are listed too. After you pick one, a gallery of pictures under the image takes you to the next. See <a href="./many-images.html">Folders, Zips and Series</a>.</li><li><strong>An address</strong>: <code>https://</code>, <code>s3://</code> or <code>gs://</code>, or a Zenodo file link that ends in <code>/content</code>. Paste it under <strong>Open Image</strong>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>Channels</strong> with the names and colours NIS-Elements gave them, such as <code>CSU green RNA</code>.</li><li><strong>Colour camera images</strong> (brightfield, H&amp;E) as a colour photograph, not as three fluorescence channels.</li><li><strong>XY positions</strong> of a multipoint experiment. Click <strong>Series</strong> on the status bar for a gallery of pictures under the image, one per position, and click one to open it. Each has the name the file gives it, or Position 1, Position 2 and on. On a phone, pick from the <strong>Series</strong> list in the side panel. See <a href="./many-images.html#series-inside-one-file">Series Inside One File</a>.</li><li><strong>Z and time.</strong> Sliders step through the planes. A Z-stack can also be viewed in 3D. See <a href="./3d-rendering.html">3D Rendering</a>.</li><li><strong>8, 12, 14 and 16-bit data.</strong> 12 and 14-bit data open with a display range that fits their depth.</li><li><strong>Files of every ND2 generation</strong>: today&#39;s files, older files that keep their metadata as XML, and the first ND2 format, whose frames are JPEG 2000.</li><li><strong>Pixel size, Z step and time interval</strong> from the file. To set your own, see <a href="./calibration.html">Pixel Size and Magnification</a>.</li></ul><p>An ND2 stores one resolution. The viewer makes the lower resolutions itself, so a large image zooms out and opens in 3D.</p><h2 id="if-a-file-does-not-open" tabindex="-1">If a File Does Not Open <a class="header-anchor" href="#if-a-file-does-not-open" aria-label="Permalink to &quot;If a File Does Not Open&quot;">​</a></h2><p>The viewer tells you why.</p><table tabindex="0"><thead><tr><th>What the file has</th><th>What the viewer says</th></tr></thead><tbody><tr><td>Frames saved with lossy (JPEG) compression</td><td>This ND2 is saved with lossy compression, which the viewer cannot read yet.</td></tr><tr><td>A spectral or custom loop that is not channels, Z, time or XY positions</td><td>This ND2 has a spectral or custom loop, which the viewer does not show yet.</td></tr><tr><td>Samples that are not 8 or 16-bit whole numbers, such as 32-bit</td><td>This ND2 has a pixel type the viewer cannot read yet (32-bit).</td></tr><tr><td>One plane of all channels over 256 MB</td><td>too large to open without a pyramid. Convert it to OME-Zarr to open it here.</td></tr><tr><td>A file that is cut short, or a damaged chunk map</td><td>This ND2 looks damaged or incomplete.</td></tr></tbody></table><p><a href="https://www.find-nuclei.com/blog/how-to-convert-to-ome-zarr" target="_blank" rel="noreferrer">Convert to OME-Zarr</a> to open a very large image with every resolution.</p><h2 id="public-nd2-files-to-try" tabindex="-1">Public ND2 Files to Try <a class="header-anchor" href="#public-nd2-files-to-try" aria-label="Permalink to &quot;Public ND2 Files to Try&quot;">​</a></h2><ul><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F12734440%2Ffiles%2FHE_002.nd2%2Fcontent" target="_blank" rel="noreferrer">HE_002.nd2</a>: an H&amp;E section from a colour camera. George Campbell, <a href="https://zenodo.org/records/12734440" target="_blank" rel="noreferrer">Zenodo 12734440</a>, CC BY 4.0.</li><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F10277961%2Ffiles%2FMRAP1%2520KO%2520DN_10X03.nd2%2Fcontent" target="_blank" rel="noreferrer">MRAP1 KO DN_10X03.nd2</a>: a stained section, brightfield. hfriedman97, <a href="https://zenodo.org/records/10277961" target="_blank" rel="noreferrer">Zenodo 10277961</a>, CC BY 4.0.</li><li><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fzenodo.org%2Fapi%2Frecords%2F17186598%2Ffiles%2FExperiment_0001.nd2%2Fcontent" target="_blank" rel="noreferrer">Experiment_0001.nd2</a>: a Z-stack of 17 planes. Bob Goldstein, <a href="https://zenodo.org/records/17186598" target="_blank" rel="noreferrer">Zenodo 17186598</a>, CC BY 4.0.</li></ul><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a file by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. An ND2 keeps its map at its end, so the viewer also asks for the file&#39;s size. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses <code>HE_002.nd2</code>, George Campbell, <a href="https://zenodo.org/records/12734440" target="_blank" rel="noreferrer">Zenodo 12734440</a>, CC BY 4.0. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The file is read in your browser. Opening one counts as one opened image of the kind &quot;Nikon ND2 file&quot;. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p>',19))])}const y=a(c,[["render",p]]);export{w as __pageData,y as default};
